param([string]$BaseUrl='http://localhost:8080')
$ErrorActionPreference='Stop';function E($a,$b,$n){if($a-ne$b){throw "$n expected=$b actual=$a"}};function I($m,$p,$b=$null,$h=$null){$x=@{Method=$m;Uri="$BaseUrl$p";SkipHttpErrorCheck=$true};if($h){$x.Headers=$h};if($null-ne$b){$x.ContentType='application/json';$x.Body=$b|ConvertTo-Json -Compress};$r=Invoke-WebRequest @x;[pscustomobject]@{s=[int]$r.StatusCode;j=$r.Content|ConvertFrom-Json}}
$u="order_state_$(Get-Random -Minimum 100000 -Maximum 999999)";$r=I POST '/api/auth/register' @{username=$u;password='OrderState_2026'};$h=@{Authorization="Bearer $($r.j.data.token)"};$a=I POST '/api/addresses' @{receiverName='Order';phone='13800138000';province='上海市';city='上海市';district='浦东新区';detail='状态';defaultAddress=$true} $h;$c1=I POST '/api/cart-items' @{productId=1;quantity=1} $h;$c2=I POST '/api/cart-items' @{productId=3;quantity=1} $h;$t=I POST '/api/orders/tokens' @{cartItemIds=@($c1.j.data.id,$c2.j.data.id)} $h;$o=I POST '/api/orders' @{addressId=$a.j.data.id;cartItemIds=@($c1.j.data.id,$c2.j.data.id);idempotencyToken=$t.j.data.token} $h;E $o.s 200 'ORDER-007';E (I GET '/api/cart-items' $null $h).j.data.Count 0 'ORDER-007 cart';$x=I POST "/api/orders/$($o.j.data.id)/cancel" $null $h;E $x.s 200 'ORDER-029';$again=I POST "/api/orders/$($o.j.data.id)/cancel" $null $h;E $again.s 409 'ORDER-033';$pay=I POST "/api/orders/$($o.j.data.id)/pay" $null $h;E $pay.s 409 'ORDER-038';Write-Host 'PASS: order full checkout and state edge.'
